# SECTION 04 — GAMIFICATION — XP, BADGES, COUNTERS
# Original: app/gamification
# Purpose: grade_hidden_tests, type_along_check, award_xp, counters, BADGES (22), difficulty_stars, awarded_badge_ids, daily_xp_series
#==============================================================================

def grade_hidden_tests(code, func_name, cases, timeout=2.5):
    """LeetCode-style hidden test grading: run func_name against many inputs.

    cases: list of (args_tuple, expected)
    Returns (all_passed, details) where details is list of {args, expected, got, passed, error}
    """
    details = []
    all_ok = True
    # ensure function exists by running code once
    for args, expected in cases:
        # build a tiny harness that calls the function and prints repr
        args_repr = ", ".join(repr(a) for a in (args if isinstance(args, tuple) else (args,)))
        harness = code + f"\n\nprint(repr({func_name}({args_repr})))\n"
        res = run_user_code(harness, timeout=timeout)
        got = (res.get("output") or "").strip()
        exp = repr(expected)
        passed = res.get("ok") and got == exp
        if not passed:
            all_ok = False
        details.append({"args": args, "expected": exp, "got": got, "passed": passed, "error": res.get("error") or res.get("explained")})
    return all_ok, details

def type_along_check(target_code, typed_code):
    """Type-along project validator: compare typed code line-by-line to target, ignoring trailing whitespace."""
    target_lines = [l.rstrip() for l in target_code.strip().splitlines()]
    typed_lines = [l.rstrip() for l in typed_code.strip().splitlines()]
    result = []
    for i, t in enumerate(target_lines):
        got = typed_lines[i] if i < len(typed_lines) else ""
        result.append({"line": i+1, "expected": t, "got": got, "ok": t == got})
    # extra lines beyond target are errors
    if len(typed_lines) > len(target_lines):
        for i in range(len(target_lines), len(typed_lines)):
            result.append({"line": i+1, "expected": "", "got": typed_lines[i], "ok": False})
    return result


# ------------------------------------------------------------------
# Example + Muscle-Memory + Drill helpers — learn by seeing, then
# by typing, then by remembering with lots of spaced review
# ------------------------------------------------------------------
# “Examples people can learn through” + “muscle memory for that type of
# code and understanding it with lots of review” lives here so the
# LearningPage + DrillHubPage both stay thin.
EXAMPLE_XP = 3
MUSCLE_XP = 6
DRILL_XP = 5
MUSCLE_REPS_NEEDED = 3  # perfect retypes in a row before the step counts

# Drill intervals are deliberately tighter than REVIEW_INTERVALS so the
# learner sees the same pattern many times in the first week (lots of
# review), then less often as it sticks.
DRILL_INTERVALS = [0, 1, 2, 4, 7, 14, 30]

def muscle_key(level, lesson_idx, step_idx):
    return f"muscle_{level}_{lesson_idx}_{step_idx}"

def example_key(level, lesson_idx, step_idx):
    return f"example_{level}_{lesson_idx}_{step_idx}"

def drill_key_for_example(level, lesson_idx):
    return f"drill_{level}_{lesson_idx}"

def muscle_progress(progress):
    return progress.setdefault("muscle_reps", {})

def example_progress(progress):
    return progress.setdefault("example_seen", {})

def drill_reviews(progress):
    return progress.setdefault("drill_reviews", {})

def record_muscle_rep(progress, level, lesson_idx, step_idx, perfect):
    """Track muscle-memory reps: perfect -> +1 towards 3, miss -> reset.

    Returns (reps_now, completed) where completed is True when the 3-in-a-row
    threshold is hit. Caller should award XP + schedule spaced review on completed.
    """
    key = muscle_key(level, lesson_idx, step_idx)
    reps = muscle_progress(progress)
    if perfect:
        reps[key] = int(reps.get(key, 0) or 0) + 1
    else:
        reps[key] = 0
    now = int(reps.get(key, 0))
    completed = now >= MUSCLE_REPS_NEEDED
    if completed:
        # reset streak so the next time they revisit it's fresh, but keep a marker
        reps[key] = 0
        progress.setdefault("muscle_mastered", {})[key] = progress.get("muscle_mastered", {}).get(key, 0) + 1
    return now, completed

def muscle_rep_count(progress, level, lesson_idx, step_idx):
    return int(muscle_progress(progress).get(muscle_key(level, lesson_idx, step_idx), 0) or 0)

def mark_example_seen(progress, level, lesson_idx, step_idx):
    key = example_key(level, lesson_idx, step_idx)
    if key not in example_progress(progress):
        example_progress(progress)[key] = date.today().isoformat()
        return True
    return False

def was_example_seen(progress, level, lesson_idx, step_idx):
    return example_key(level, lesson_idx, step_idx) in progress.get("example_seen", {})

def schedule_drill_review(progress, level, lesson_idx):
    """Schedule a drill review for a lesson's muscle pattern. Lots of early reviews."""
    revs = drill_reviews(progress)
    key = drill_key_for_example(level, lesson_idx)
    if key in revs:
        return False
    revs[key] = {"due": (date.today() + timedelta(days=DRILL_INTERVALS[1])).isoformat(), "interval_idx": 1}
    progress["drill_reviews"] = revs
    return True

def grade_drill_review(progress, level, lesson_idx, correct):
    revs = drill_reviews(progress)
    key = drill_key_for_example(level, lesson_idx)
    entry = revs.get(key) or {"interval_idx": 1, "due": ""}
    idx = int(entry.get("interval_idx", 1))
    if correct:
        nxt = min(idx + 1, len(DRILL_INTERVALS) - 1)
    else:
        nxt = 1  # lots of review — don’t drop to 0, keep due tomorrow
    # if due is today (interval 0) we use 1 day
    days = DRILL_INTERVALS[nxt]
    if days <= 0:
        days = 1
    entry["interval_idx"] = nxt
    entry["due"] = (date.today() + timedelta(days=days)).isoformat()
    revs[key] = entry
    progress["drill_reviews"] = revs

def due_drill_reviews(progress, lesson_sets, today=None):
    today = today or date.today().isoformat()
    revs = progress.get("drill_reviews", {}) or {}
    out = []
    for key, entry in revs.items():
        if entry.get("due", "") > today:
            continue
        # key is drill_Level_idx
        if not key.startswith("drill_"):
            continue
        rest = key[6:]  # Level_idx
        if "_" not in rest:
            continue
        level, idx_str = rest.rsplit("_", 1)
        try:
            lesson_idx = int(idx_str)
        except ValueError:
            continue
        lessons = lesson_sets.get(level, [])
        if not (0 <= lesson_idx < len(lessons)):
            continue
        lesson = lessons[lesson_idx]
        out.append({
            "level": level, "lesson_idx": lesson_idx,
            "title": lesson.get("title",""),
            "unit": lesson.get("unit",""),
            "example": lesson.get("example",""),
            "interval_idx": entry.get("interval_idx",1),
            "key": key,
        })
    return out

def due_drill_reviews_count(progress, lesson_sets):
    return len(due_drill_reviews(progress, lesson_sets))

def build_example_library(lesson_sets):
    """Flatten every lesson's runnable example into a gallery list.

    Each entry: {level, lesson_idx, title, unit, code, explanation, takeaways}
    Used by DrillHubPage gallery + by lesson enrichment (so every lesson
    gets at least one walkthrough).
    """
    lib = []
    for level, lessons in (lesson_sets or {}).items():
        for idx, les in enumerate(lessons):
            code = (les.get("example") or "").strip()
            if not code:
                continue
            lib.append({
                "level": level, "lesson_idx": idx,
                "title": les.get("title",""), "unit": les.get("unit",""),
                "topic": les.get("topic",""),
                "code": code,
                "summary": les.get("summary",""),
                "takeaways": les.get("key_takeaways",""),
                "why": les.get("why_it_matters",""),
            })
    return lib

def explain_example_line_by_line(code):
    """Very small heuristic explainer so every example is learn-through, not just copy.

    Returns list of (line, plain_english) for the 2-4 most important lines.
    Keeps it offline and instant (no LLM).
    """
    lines = [l.rstrip() for l in code.strip().splitlines() if l.strip()]
    notes = []
    for ln in lines:
        stripped = ln.strip()
        if stripped.startswith("import ") or stripped.startswith("from "):
            notes.append((ln, "Bring a helper module into your program so you can call its tools."))
        elif "for " in stripped and " in " in stripped:
            notes.append((ln, "Loop: do the indented line once for each item."))
        elif stripped.startswith("def "):
            notes.append((ln, "Define a reusable recipe (function) you can call by name later."))
        elif "print(" in stripped:
            notes.append((ln, "Show a value on the screen so you can see what the code did."))
        elif "if " in stripped:
            notes.append((ln, "Branch: only run the indented line when the test is True."))
        elif "=" in stripped and not any(op in stripped for op in ["==","!=","<=",">="]):
            # simple assignment
            notes.append((ln, "Store a value in a named box (variable) for later use."))
        elif "return" in stripped:
            notes.append((ln, "Send a value back to whoever called the function."))
        elif "class " in stripped:
            notes.append((ln, "Blueprint for objects: define what data and actions they have."))
        elif ".upper(" in stripped or ".lower(" in stripped or ".replace(" in stripped:
            notes.append((ln, "Call a string helper that returns a new, transformed string."))
        else:
            notes.append((ln, "Run this line and observe how it changes the variables."))
        if len(notes) >= 4:
            break
    # keep at most 4
    return notes[:4]


def award_xp(progress, amount, label=""):
    progress["xp"] = progress.get("xp", 0) + amount
    events = progress.get("events", [])
    today = date.today().isoformat()
    events.append({
        "date": today,
        "xp": amount,
        "label": label,
    })
    if len(events) > 500:
        del events[:-500]
    progress["events"] = events
    _update_heatmap(progress, today)
    # weekly quest progress: daily challenge and projects count extra
    if label in ("daily_challenge", "project", "lesson_complete"):
        _increment_weekly_activity(progress)


def _count_completed_steps(p):
    return sum(1 for v in p.get("completed_steps", {}).values() if v)


def _count_passed_projects(p):
    return sum(
        1 for log in p.get("performance_log", {}).values() if log.get("project_passed")
    )


def _count_lessons(p):
    # Count lessons done in current level plus any earlier levels that were auto-checked via quiz skip.
    total = len(p.get("completed_lessons", []))
    cbl = p.get("completed_by_level", {})
    if isinstance(cbl, dict):
        for lv, lst in cbl.items():
            if lv != p.get("level", ""):
                total += len(lst or [])
    return total


def _count_reviews_done(p):
    return sum(
        1 for entry in p.get("reviews", {}).values() if entry.get("interval_idx", 0) > 0
    )


def _all_projects_passed(p, sets, level):
    lessons = sets.get(level, [])
    if not lessons:
        return False
    if _is_level_skipped(p, level):
        return True
    for i in range(len(lessons)):
        key = attempt_key(level, i)
        if not p.get("performance_log", {}).get(key, {}).get("project_passed"):
            return False
    return True


def _no_hint_projects_passed(p, sets, level, count):
    lessons = sets.get(level, [])
    found = 0
    for i in range(len(lessons)):
        key = attempt_key(level, i)
        if p.get("performance_log", {}).get(key, {}).get("project_passed"):
            if not _hint_key_used(p, sets, level, i):
                found += 1
    return found >= count


def _hint_key_used(p, sets, level, lesson_idx):
    """A project counts as 'hint-free' if the learner never unlocked a progressive hint."""
    key = project_hint_key(level, lesson_idx)
    return int(p.get("project_hints", {}).get(key, 0) or 0) > 0


