#==============================================================================
# SECTION 06 — REVIEWS — SPACED REPETITION (SM-2 lite)
# Original: app/reviews
# Purpose: REVIEW_INTERVALS, review_key, review_schedule, schedule_review, grade_review, due_reviews, due_reviews_count
#==============================================================================

REVIEW_INTERVALS = [1, 2, 4, 8, 16, 32, 60]


def review_key(level, lesson_idx):
    return f"{level}_{lesson_idx}"


def review_schedule(progress):
    return progress.setdefault("reviews", {})


def schedule_review(progress, level, lesson_idx):
    """First time a lesson is mastered, schedule its first review for +1 day."""
    sched = review_schedule(progress)
    key = review_key(level, lesson_idx)
    entry = sched.get(key)
    if entry:
        return False
    sched[key] = {
        "due": (date.today() + timedelta(days=REVIEW_INTERVALS[0])).isoformat(),
        "interval_idx": 0,
    }
    progress["reviews"] = sched
    return True


def grade_review(progress, level, lesson_idx, correct):
    """After a review, reschedule: correct -> longer interval, wrong -> reset to 1 day."""
    sched = review_schedule(progress)
    key = review_key(level, lesson_idx)
    entry = sched.get(key) or {"interval_idx": 0, "due": ""}
    if correct:
        nxt = min(entry.get("interval_idx", 0) + 1, len(REVIEW_INTERVALS) - 1)
    else:
        nxt = 0
    entry["interval_idx"] = nxt
    entry["due"] = (date.today() + timedelta(days=REVIEW_INTERVALS[nxt])).isoformat()
    sched[key] = entry
    progress["reviews"] = sched


def due_reviews(progress, lesson_sets, today=None):
    """Return list of due review entries: {level, lesson_idx, title, question,
    answer, takeaways, interval_idx}."""
    today = today or date.today().isoformat()
    sched = review_schedule(progress)
    out = []
    for key, entry in sched.items():
        if entry.get("due", "") > today:
            continue
        if "_" not in key:
            continue
        level, idx_str = key.rsplit("_", 1)
        try:
            lesson_idx = int(idx_str)
        except ValueError:
            continue
        lessons = lesson_sets.get(level, [])
        if not (0 <= lesson_idx < len(lessons)):
            continue
        lesson = lessons[lesson_idx]
        out.append({
            "level": level,
            "lesson_idx": lesson_idx,
            "title": lesson.get("title", ""),
            "question": lesson.get("review_question", ""),
            "answer": lesson.get("review_answer", ""),
            "takeaways": lesson.get("key_takeaways", ""),
            "answer_prompt": lesson.get("review_answer", ""),
            "interval_idx": entry.get("interval_idx", 0),
        })
    return out


def due_reviews_count(progress, lesson_sets):
    return len(due_reviews(progress, lesson_sets))


# ------------------------------------------------------------------
# Example + Muscle enrichment — lessons learn-through, muscle-memory, lots of review
# ------------------------------------------------------------------
# Every lesson already has a runnable `example` at lesson level. This helper
# turns that raw code into two learn-through steps that are inserted into the
# lesson's `steps` list so the learner first SEEs the pattern (example
# walkthrough) and then TYPES it from muscle memory (retype drill). The
# steps are idempotent — if a lesson already contains an `example` or
# `muscle` type we leave it alone, so manually-authored lessons are never
# clobbered. Call once after `build_lesson_sets()` in LearningPage.
def ensure_example_and_muscle_steps(lesson_sets):
    """Inject an Example Walkthrough + Muscle Memory retype into each lesson.

    * Example step: shows the lesson's `example` with line-by-line plain-English
      notes from `explain_example_line_by_line` and a Predict-the-output mini-quiz.
    * Muscle step: requires the learner to retype the exact `example` code.
      Uses `type_along_check` and needs MUSCLE_REPS_NEEDED perfect copies in a row.
      On completion it awards MUSCLE_XP and schedules a frequent drill review
      (lots of review: due again in 1,2,4,7 days).
    Returns the same dict (mutated in place) for chaining.
    """
    try:
        for level, lessons in (lesson_sets or {}).items():
            for li, lesson in enumerate(lessons):
                steps = lesson.get("steps") or []
                # idempotence: don't double-inject
                has_example = any(s.get("type") == "example" for s in steps)
                has_muscle = any(s.get("type") == "muscle" for s in steps)
                # Need a runnable example to base the steps on
                base_code = (lesson.get("example") or "").strip()
                if not base_code:
                    continue
                # --- find insertion points ---
                # Example walkthrough should sit after the first concept, or at 1
                # Muscle retype should sit after the first practice/fill/debug, or at 2
                if not has_example:
                    example_step = {
                        "type": "example",
                        "title": f"Walkthrough: {lesson.get('title','')} example",
                        "code": base_code,
                        "explanation": lesson.get("summary","") or lesson.get("key_takeaways","")[:220],
                        "instruction": "Study the annotated example on the left, predict what it prints, then run it on the right to check your understanding.",
                        "hint": "Read each annotation, trace the variables, then hit Run to see the real output.",
                        "success_msg": "Nice — you studied the pattern. Next, build muscle memory by retyping it.",
                    }
                    # insert after first concept if present, else near top
                    insert_at = 1
                    for i, s in enumerate(steps):
                        if s.get("type") == "concept":
                            insert_at = i + 1
                            break
                    steps.insert(min(insert_at, len(steps)), example_step)
                if not has_muscle:
                    # Recompute has_example offset for second insertion
                    muscle_step = {
                        "type": "muscle",
                        "title": f"Muscle memory: retype the {lesson.get('title','')} pattern",
                        "instruction": "Retype the example exactly — every character matters. Get it perfect 3 times in a row to lock it into muscle memory.",
                        "target_code": base_code,
                        "starter_code": "# Retype the example exactly here\n",
                        "hint": "Match indentation, quotes, and parentheses exactly. Count spaces — 4 per indent.",
                        "success_msg": "Muscle memory locked! You typed it perfectly 3 for 3. Lots of review will bring it back soon.",
                    }
                    # place after first practice/debug/fill, else before final review
                    insert_at = len(steps) - 1
                    for i, s in enumerate(steps):
                        if s.get("type") in ("practice","debug","fill","muscle"):
                            insert_at = i + 1
                            break
                    # ensure we don't push past end and keep review last
                    last_type = steps[-1].get("type") if steps else ""
                    if last_type == "review" and insert_at == len(steps):
                        insert_at = len(steps) - 1
                    steps.insert(min(max(insert_at, 1), len(steps)), muscle_step)
                lesson["steps"] = steps
    except Exception:
        pass
    return lesson_sets



